/**
 * The sample reserve: a FICTIONAL park used by the prototype.
 *
 * It is generated by a seeded program, so every app draws the same reserve. Its boundary, pans,
 * dry river and track network are invented. They are placed at real coordinates in western
 * Botswana only so that maps, GPS distances and routing behave as they would in a real pack; they
 * do not match the ground there and must never be used to navigate.
 *
 * Track statuses in the sample: "verified" (reviewed), "gps" (confirmed by 3 or more synthetic
 * trips), "predicted" (a sample of what an imagery model might suggest, with a confidence level),
 * and "closed" (a patrol track, never shown or routed).
 *
 * A real park pack (tools/map-pack) uses the same `Reserve` shape, so routing and guidance work
 * unchanged. Its edges are OpenStreetMap ways with status "osm", shown as "OSM, not verified"
 * until GPS trips confirm them; it has no pans or river (water comes from the base map) and no
 * predicted tracks.
 */

import { lineLengthMeters, metersToDegrees, pointInRing, type LonLat } from "./geo.ts";

export type TrackStatus = "verified" | "gps" | "osm" | "predicted" | "closed";
export type Confidence = "high" | "medium" | "low";

export type TrackNode = { id: string; at: LonLat; kind: "junction" | "gate" | "camp"; name?: string };

export type TrackEdge = {
  id: string;
  from: string;
  to: string;
  line: LonLat[];
  status: TrackStatus;
  confidence?: Confidence;
  /** Synthetic trips that confirmed a "gps" edge. */
  trips?: number;
  /** Month of the imagery a "predicted" edge would come from (sample). */
  imageryMonth?: string;
  lengthMeters: number;
  /** Where the edge came from; "osm" edges carry the way id and its tags. */
  source?: "sample" | "osm";
  osmWayId?: number;
  highway?: string;
  surface?: string;
  tracktype?: string;
  smoothness?: string;
  name?: string;
  /** Set when OSM tells drivers to avoid the way; routing makes it four times as expensive. */
  caution?: string;
};

export type Pan = { name: string; ring: LonLat[] };

export type Reserve = {
  id: string;
  name: string;
  version: string;
  notice: string;
  centre: LonLat;
  /** [west, south, east, north] */
  bounds: [number, number, number, number];
  boundary: LonLat[];
  pans: Pan[];
  river: LonLat[];
  nodes: TrackNode[];
  edges: TrackEdge[];
  /** "real" for a park pack built from OpenStreetMap; absent or "sample" for the sample reserve. */
  kind?: "sample" | "real";
};

/** Label for a track's status, as the map key and the route sheet say it. */
export const TRACK_STATUS_LABEL: Record<TrackStatus, string> = {
  verified: "Verified track",
  gps: "GPS-confirmed track",
  osm: "OSM, not verified",
  predicted: "Predicted, not verified",
  closed: "Closed",
};

export const SAMPLE_RESERVE_ID = "sample-reserve";
export const SAMPLE_RESERVE_NOTICE =
  "Fictional sample reserve. Its shapes and tracks are generated and do not match the ground at these coordinates. Do not navigate by it.";

const CENTRE: LonLat = [22.4, -21.3];
const SEED = 20_261_007;

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const round5 = (value: number) => Math.round(value * 1e5) / 1e5;

let cached: Reserve | null = null;

/** Build (once) and return the sample reserve. Deterministic: the same seed gives the same park. */
export function sampleReserve(): Reserve {
  if (cached) return cached;
  const rand = mulberry32(SEED);
  const deg = metersToDegrees(CENTRE[1]);
  const toLonLat = (x: number, y: number): LonLat => [round5(CENTRE[0] + x * deg.lon), round5(CENTRE[1] + y * deg.lat)];

  // Boundary: a lobed oval about 35 by 28 km.
  const p1 = rand() * Math.PI * 2;
  const p2 = rand() * Math.PI * 2;
  const radius = (theta: number) => 14_000 * (1 + 0.1 * Math.sin(2 * theta + p1) + 0.07 * Math.sin(3 * theta + p2));
  const stretch = 1.25;
  const inside = (x: number, y: number, margin = 1) => Math.hypot(x / stretch, y) < radius(Math.atan2(y, x / stretch)) * margin;
  const boundaryXY: [number, number][] = [];
  for (let k = 0; k < 72; k += 1) {
    const theta = (k / 72) * Math.PI * 2;
    const r = radius(theta) * (1 + (rand() - 0.5) * 0.025);
    boundaryXY.push([Math.cos(theta) * r * stretch, Math.sin(theta) * r]);
  }
  const boundary = [...boundaryXY, boundaryXY[0]].map(([x, y]) => toLonLat(x, y));

  // Junctions on a jittered grid inside the boundary.
  const cols = 7;
  const rows = 6;
  const spacing = 4_300;
  const grid: (string | null)[][] = [];
  const xy = new Map<string, [number, number]>();
  const nodes: TrackNode[] = [];
  let nodeCount = 0;
  for (let i = 0; i < cols; i += 1) {
    grid.push([]);
    for (let j = 0; j < rows; j += 1) {
      const x = (i - (cols - 1) / 2) * spacing * 1.12 + (rand() - 0.5) * 1_700;
      const y = (j - (rows - 1) / 2) * spacing + (rand() - 0.5) * 1_700;
      if (!inside(x, y, 0.84)) {
        grid[i].push(null);
        continue;
      }
      const id = `n${(nodeCount += 1)}`;
      grid[i].push(id);
      xy.set(id, [x, y]);
      nodes.push({ id, at: toLonLat(x, y), kind: "junction" });
    }
  }

  // Candidate edges between grid neighbours; a random spanning tree keeps the network connected.
  type Candidate = { a: string; b: string; w: number };
  const candidates: Candidate[] = [];
  for (let i = 0; i < cols; i += 1) {
    for (let j = 0; j < rows; j += 1) {
      const a = grid[i][j];
      if (!a) continue;
      const right = i + 1 < cols ? grid[i + 1][j] : null;
      const up = j + 1 < rows ? grid[i][j + 1] : null;
      if (right) candidates.push({ a, b: right, w: rand() });
      if (up) candidates.push({ a, b: up, w: rand() });
    }
  }
  candidates.sort((p, q) => p.w - q.w);
  const parent = new Map(nodes.map((n) => [n.id, n.id]));
  const find = (id: string): string => {
    let root = id;
    while (parent.get(root) !== root) root = parent.get(root)!;
    parent.set(id, root);
    return root;
  };
  const tree: Candidate[] = [];
  const extra: Candidate[] = [];
  for (const c of candidates) {
    const ra = find(c.a);
    const rb = find(c.b);
    if (ra !== rb) {
      parent.set(ra, rb);
      tree.push(c);
    } else extra.push(c);
  }
  const loops = extra.filter(() => rand() < 0.5);

  // Gentle curves so the tracks read as tracks, not a grid.
  const curve = (a: [number, number], b: [number, number]): LonLat[] => {
    const amp1 = (rand() - 0.5) * 1_000;
    const amp2 = (rand() - 0.5) * 500;
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len;
    const ny = dx / len;
    const steps = 12;
    const line: LonLat[] = [];
    for (let s = 0; s <= steps; s += 1) {
      const t = s / steps;
      const wobble = s === 0 || s === steps ? 0 : (rand() - 0.5) * 70;
      const off = amp1 * Math.sin(Math.PI * t) + amp2 * Math.sin(2 * Math.PI * t) + wobble;
      line.push(toLonLat(a[0] + dx * t + nx * off, a[1] + dy * t + ny * off));
    }
    return line;
  };

  const edges: TrackEdge[] = [];
  let edgeCount = 0;
  const addEdge = (a: string, b: string, status: TrackStatus, extraProps: Partial<TrackEdge> = {}) => {
    const line = curve(xy.get(a)!, xy.get(b)!);
    edges.push({ id: `e${(edgeCount += 1)}`, from: a, to: b, line, status, lengthMeters: Math.round(lineLengthMeters(line)), ...extraProps });
  };
  for (const c of tree) {
    if (rand() < 0.68) addEdge(c.a, c.b, "verified");
    else addEdge(c.a, c.b, "gps", { trips: 3 + Math.floor(rand() * 12) });
  }
  const confidences: Confidence[] = ["high", "medium", "low"];
  loops.forEach((c, index) => {
    if (index === 1) {
      addEdge(c.a, c.b, "closed");
      return;
    }
    const roll = rand();
    if (roll < 0.5) addEdge(c.a, c.b, "predicted", { confidence: confidences[Math.floor(rand() * 3)], imageryMonth: "2026-06" });
    else if (roll < 0.85) addEdge(c.a, c.b, "gps", { trips: 3 + Math.floor(rand() * 9) });
    else addEdge(c.a, c.b, "verified");
  });

  // A gate on the southern boundary, joined to the nearest junction by a verified track.
  const southTheta = -Math.PI / 2;
  const gateXY: [number, number] = [0, -radius(southTheta) * 0.985];
  const nearest = (point: [number, number], pool: TrackNode[]) =>
    pool.reduce((best, node) => {
      const [x, y] = xy.get(node.id)!;
      const dist = Math.hypot(x - point[0], y - point[1]);
      return dist < best.dist ? { node, dist } : best;
    }, { node: pool[0], dist: Number.POSITIVE_INFINITY }).node;
  const gateLink = nearest(gateXY, nodes);
  xy.set("gate", gateXY);
  nodes.push({ id: "gate", at: toLonLat(...gateXY), kind: "gate", name: "South gate" });
  addEdge("gate", gateLink.id, "verified");

  // Pans near a few junctions; two junctions beside pans become camps.
  const panNames = ["North Pan", "Twin Pan", "Salt Pan", "Long Pan"];
  const pans: Pan[] = [];
  const junctions = nodes.filter((n) => n.kind === "junction");
  const used = new Set<string>();
  for (const name of panNames) {
    let host = junctions[Math.floor(rand() * junctions.length)];
    let guard = 0;
    while (used.has(host.id) && guard < 20) {
      host = junctions[Math.floor(rand() * junctions.length)];
      guard += 1;
    }
    used.add(host.id);
    const [hx, hy] = xy.get(host.id)!;
    const angle = rand() * Math.PI * 2;
    const cx = hx + Math.cos(angle) * 1_300;
    const cy = hy + Math.sin(angle) * 1_300;
    const rx = 500 + rand() * 800;
    const ry = rx * (0.55 + rand() * 0.35);
    const tilt = rand() * Math.PI;
    const ring: LonLat[] = [];
    for (let k = 0; k < 28; k += 1) {
      const t = (k / 28) * Math.PI * 2;
      const wobble = 1 + (rand() - 0.5) * 0.12;
      const ex = Math.cos(t) * rx * wobble;
      const ey = Math.sin(t) * ry * wobble;
      ring.push(toLonLat(cx + ex * Math.cos(tilt) - ey * Math.sin(tilt), cy + ex * Math.sin(tilt) + ey * Math.cos(tilt)));
    }
    ring.push(ring[0]);
    pans.push({ name, ring });
  }
  const campHosts = [...used].slice(0, 2);
  const campNames = ["Pan camp", "Acacia camp"];
  campHosts.forEach((id, index) => {
    const node = nodes.find((n) => n.id === id)!;
    node.kind = "camp";
    node.name = campNames[index];
  });

  // A dry river crossing the reserve from west to east.
  const q1 = rand() * Math.PI * 2;
  const q2 = rand() * Math.PI * 2;
  const river: LonLat[] = [];
  for (let x = -19_000; x <= 19_000; x += 700) {
    const y = 2_600 + 2_400 * Math.sin(x / 7_000 + q1) + 700 * Math.sin(x / 2_300 + q2);
    if (inside(x, y, 0.995)) river.push(toLonLat(x, y));
  }

  const lons = boundary.map((p) => p[0]);
  const lats = boundary.map((p) => p[1]);
  cached = {
    id: SAMPLE_RESERVE_ID,
    name: "Sample reserve",
    version: "2026.10.1",
    notice: SAMPLE_RESERVE_NOTICE,
    centre: CENTRE,
    bounds: [Math.min(...lons), Math.min(...lats), Math.max(...lons), Math.max(...lats)],
    boundary,
    pans,
    river,
    nodes,
    edges,
  };
  return cached;
}

/** True when a point is inside the reserve boundary. */
export function isInsideReserve(reserve: Reserve, point: LonLat): boolean {
  return pointInRing(point, reserve.boundary);
}

/** Tracks anyone may see: closed patrol tracks are never shown. */
export function visibleEdges(reserve: Reserve, options: { predicted: boolean }): TrackEdge[] {
  return reserve.edges.filter((edge) => edge.status !== "closed" && (options.predicted || edge.status !== "predicted"));
}

type Feature = { type: "Feature"; properties: Record<string, string | number | boolean | null>; geometry: { type: string; coordinates: unknown } };
export type FeatureCollection = { type: "FeatureCollection"; features: Feature[] };

const fc = (features: Feature[]): FeatureCollection => ({ type: "FeatureCollection", features });

/** GeoJSON layers for a map. Closed tracks are left out here, before anything is drawn. */
export function reserveGeoJSON(reserve: Reserve) {
  return {
    boundary: fc([{ type: "Feature", properties: { name: reserve.name }, geometry: { type: "Polygon", coordinates: [reserve.boundary] } }]),
    pans: fc(reserve.pans.map((pan) => ({ type: "Feature", properties: { name: pan.name }, geometry: { type: "Polygon", coordinates: [pan.ring] } }))),
    river: fc([{ type: "Feature", properties: { name: "Dry river" }, geometry: { type: "LineString", coordinates: reserve.river } }]),
    tracks: fc(
      visibleEdges(reserve, { predicted: true }).map((edge) => ({
        type: "Feature",
        properties: { id: edge.id, status: edge.status, confidence: edge.confidence ?? null, trips: edge.trips ?? null, length: edge.lengthMeters },
        geometry: { type: "LineString", coordinates: edge.line },
      })),
    ),
    places: fc(
      reserve.nodes
        .filter((node) => node.kind !== "junction")
        .map((node) => ({ type: "Feature", properties: { name: node.name ?? "", kind: node.kind }, geometry: { type: "Point", coordinates: node.at } })),
    ),
  };
}
